@import "tailwindcss";

:root {
  --ink: #000000;
  --canvas: #ffffff;
  --surface-soft: #f3f3f3;
  --hairline: #e5e5e5;
  --block-lime: #c8f169;
  --block-lilac: #daccff;
  --block-cream: #f4efc6;
  --block-mint: #bdf3dc;
  --block-pink: #ffc7e8;
  --block-coral: #ff8f7e;
  --block-navy: #25244f;
}

@theme inline {
  --color-background: var(--canvas);
  --color-foreground: var(--ink);
  --font-sans: var(--font-outfit);
  --font-mono: var(--font-geist-mono);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 6rem;
}

body {
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font-family: var(--font-outfit), sans-serif;
  font-size: 18px;
  font-weight: 320;
  line-height: 1.45;
}

button,
a,
summary {
  -webkit-tap-highlight-color: transparent;
}

a {
  color: inherit;
  text-decoration: none;
}

:focus-visible {
  outline: 3px solid var(--ink);
  outline-offset: 4px;
}

.site-footer :focus-visible,
.tone-navy :focus-visible {
  outline-color: var(--canvas);
}

.site-header {
  position: relative;
  z-index: 20;
  background: var(--canvas);
  border-bottom: 1px solid var(--hairline);
}

.site-nav {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  width: min(100%, 1280px);
  min-height: 72px;
  margin: 0 auto;
  padding: 12px 32px;
}

.wordmark,
.footer-name {
  width: fit-content;
  font-size: 20px;
  font-weight: 540;
  letter-spacing: -0.2px;
}

.nav-links {
  display: flex;
  gap: 8px;
  align-items: center;
}

.nav-links a,
.mobile-nav a {
  min-height: 44px;
  padding: 9px 14px;
  font-size: 16px;
  font-weight: 480;
}

.nav-links a:hover,
.site-footer a:hover,
.project-links a:hover,
.accordion-copy a:hover {
  text-decoration: underline;
  text-underline-offset: 4px;
}

.nav-hire {
  justify-self: end;
}

.mobile-nav {
  display: none;
  position: relative;
}

.mobile-nav summary {
  min-width: 44px;
  min-height: 44px;
  padding: 9px 12px;
  cursor: pointer;
  font-weight: 480;
  list-style: none;
}

.mobile-nav summary::-webkit-details-marker {
  display: none;
}

.mobile-nav > div {
  position: absolute;
  top: calc(100% + 13px);
  left: 50%;
  display: grid;
  min-width: 160px;
  padding: 12px;
  background: var(--canvas);
  border: 1px solid var(--hairline);
  border-radius: 24px;
  transform: translateX(-50%);
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 10px 22px;
  border-radius: 50px;
  font-size: 20px;
  font-weight: 480;
  line-height: 1.25;
  transition:
    transform 180ms ease,
    background-color 180ms ease;
}

.button:hover {
  transform: translateY(-2px);
}

.button-primary {
  background: var(--ink);
  color: var(--canvas);
}

.button-primary:hover {
  background: var(--block-navy);
}

.button-secondary {
  background: var(--canvas);
  color: var(--ink);
}

.hero {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: min(100%, 1440px);
  min-height: calc(100svh - 72px);
  margin: 0 auto;
  padding: clamp(72px, 9vw, 128px) 32px 0;
  text-align: center;
}

.eyebrow {
  margin: 0;
  font-family: var(--font-geist-mono), monospace;
  font-size: 12px;
  font-weight: 400;
  line-height: 1.3;
  letter-spacing: 0.6px;
  text-transform: uppercase;
}

.hero h1 {
  max-width: 72rem;
  margin: 28px auto 0;
  font-size: clamp(3.25rem, 7vw, 6.5rem);
  font-weight: 340;
  line-height: 0.96;
  letter-spacing: -0.025em;
  text-wrap: balance;
}

.hero-actions {
  display: flex;
  gap: 12px;
  margin-top: 36px;
}

.cube-stage {
  position: relative;
  width: min(100%, 1120px);
  height: clamp(340px, 48vw, 610px);
  margin-top: 48px;
  overflow: hidden;
  background: var(--surface-soft);
  border-radius: 24px 24px 0 0;
  isolation: isolate;
}

.cube-stage > div {
  width: 100% !important;
  height: 100% !important;
}

.cube-fallback {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: var(--block-cream);
}

.cube-fallback span {
  position: absolute;
  width: clamp(90px, 16vw, 190px);
  aspect-ratio: 1;
  border: 3px solid var(--ink);
}

.cube-fallback span:nth-child(1) {
  background: var(--block-lilac);
  transform: translateY(-28%) rotate(30deg) skewX(-30deg) scaleY(0.86);
}

.cube-fallback span:nth-child(2) {
  background: var(--block-lime);
  transform: translate(-43%, 46%) skewY(30deg) scaleX(0.86);
}

.cube-fallback span:nth-child(3) {
  background: var(--block-coral);
  transform: translate(43%, 46%) skewY(-30deg) scaleX(0.86);
}

.capability-strip {
  overflow: hidden;
  background: var(--ink);
  color: var(--canvas);
  border-block: 1px solid var(--ink);
}

.marquee-track {
