  font-size: clamp(1.35rem, 2.5vw, 2.2rem);
  font-weight: 540;
  line-height: 1.05;
}

.accordion-copy {
  max-width: 48ch;
  padding: 0 24px 24px;
}

.accordion-copy p {
  margin: 0 0 12px;
}

.project-stack {
  position: relative;
}

.stack-card {
  display: grid;
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
  min-height: 72svh;
  margin-bottom: 128px;
  overflow: hidden;
  border: 1px solid var(--ink);
  border-radius: 24px;
}

.stack-card:last-child {
  margin-bottom: 0;
}

.stack-copy {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: clamp(28px, 5vw, 72px);
}

.stack-copy h3 {
  font-size: clamp(2.6rem, 5vw, 5rem);
}

.stack-media {
  margin: 24px;
  border-radius: 16px;
}

.contact-section {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  width: min(calc(100% - 64px), 1280px);
  min-height: 76svh;
  margin: 48px auto 176px;
  padding: clamp(48px, 9vw, 112px);
  background: var(--block-lime);
  border-radius: 24px;
}

.contact-section h2 {
  max-width: 900px;
  margin: 28px 0 20px;
  font-size: clamp(3.5rem, 7vw, 6.5rem);
  font-weight: 340;
  line-height: 0.96;
  letter-spacing: -0.025em;
}

.contact-section > p:not(.eyebrow) {
  margin: 0 0 36px;
  font-size: 22px;
}

.site-footer {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 48px;
  padding: 80px max(32px, calc((100vw - 1280px) / 2));
  background: var(--ink);
  color: var(--canvas);
}

.site-footer p {
  margin: 12px 0 0;
  font-size: 15px;
}

.site-footer nav {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px 24px;
}

.site-footer nav a {
  min-height: 44px;
  padding-block: 9px;
  font-size: 16px;
  font-weight: 480;
}

@media (min-width: 768px) {
  .project-bento {
    grid-template-rows: repeat(2, minmax(31rem, 1fr));
  }
}

@media (max-width: 959px) {
  .site-nav {
    grid-template-columns: 1fr auto auto;
    gap: 8px;
  }

  .nav-links {
    display: none;
  }

  .mobile-nav {
    display: block;
  }

  .section-heading {
    grid-template-columns: 1fr;
  }

  .project-accordion {
    min-height: 330px;
  }

  .accordion-item summary {
    padding: 18px;
  }

  .accordion-copy {
    padding-inline: 18px;
  }
}

@media (max-width: 767px) {
  html {
    scroll-padding-top: 5rem;
  }

  .site-nav {
    min-height: 64px;
    padding: 10px 18px;
  }

  .wordmark {
    font-size: 17px;
  }

  .nav-hire {
    min-height: 44px;
    padding: 8px 16px;
    font-size: 16px;
  }

  .hero {
    min-height: auto;
    padding: 80px 18px 0;
  }

  .hero h1 {
    margin-top: 22px;
    font-size: clamp(2.25rem, 11vw, 3.25rem);
    line-height: 0.98;
  }

  .hero-actions {
    width: 100%;
    margin-top: 30px;
  }

  .hero-actions .button {
    flex: 1;
    padding-inline: 14px;
  }

  .cube-stage {
    width: calc(100% + 36px);
    height: 360px;
    margin-top: 48px;
    border-radius: 0;
  }

  .chapter {
    padding: 112px 18px;
  }

  .section-heading {
    margin-bottom: 42px;
  }

  .section-heading h2 {
    font-size: clamp(2.7rem, 13vw, 4rem);
  }

  .project-bento {
    width: calc(100% + 36px);
    margin-left: -18px;
    border-radius: 0;
  }

  .project-card {
    min-height: 580px;
  }

  .field-statement,
  .contact-section {
    width: 100%;
    border-radius: 0;
  }

  .field-statement {
    padding: 88px 24px;
  }

  .field-statement h2 {
    font-size: clamp(2.65rem, 12vw, 4rem);
  }

  .field-copy {
    margin-top: 42px;
    font-size: 19px;
  }

  .project-accordion {
    display: block;
    min-height: 0;
    margin-bottom: 112px;
    border-radius: 0;
  }

  .accordion-item {
    border-right: 0;
    border-bottom: 1px solid var(--ink);
  }

  .accordion-item:last-child {
    border-bottom: 0;
  }

  .accordion-item summary {
    min-height: 136px;
  }

  .stack-card {
    grid-template-columns: 1fr;
    grid-template-rows: auto minmax(330px, 52svh);
    min-height: 75svh;
    margin-bottom: 80px;
    border-radius: 0;
  }

  .stack-copy {
    padding: 34px 24px;
  }

  .stack-copy h3 {
    font-size: clamp(2.5rem, 13vw, 4rem);
  }

  .stack-media {
    margin: 0 14px 14px;
    border-radius: 12px;
  }

  .contact-section {
    min-height: 76svh;
    margin: 24px 0 112px;
    padding: 72px 24px;
  }

  .contact-section h2 {
    font-size: clamp(3.1rem, 15vw, 5rem);
  }

  .contact-section .button {
    width: 100%;
  }

  .site-footer {
    grid-template-columns: 1fr;
    padding: 64px 24px;
  }

  .site-footer nav {
    justify-content: flex-start;
  }
}

@media (max-width: 420px) {
  .wordmark {
    max-width: 72px;
    line-height: 1;
  }

  .mobile-nav summary {
    padding-inline: 6px;
  }

  .nav-hire {
    padding-inline: 13px;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
